// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor, uint256 salt) public {
        vm.assume(actor != address(0));
        // The caller must satisfy supportsToken via Bank(msg.sender), so deploy a
        // per-actor Bank-identifier helper and drive airDrop through it.
        Caller caller = new Caller(c);
        try caller.drop() {
            // Rule: after a completed airDrop the reentrancy lock is released.
            assertTrue(c._locked() == false);
        } catch {
            // If the call reverts, the lock must still be disengaged.
            assertTrue(c._locked() == false, "lock engaged after revert");
        }
        // keep fuzz params meaningfully used
        require(salt >= 0);
    }
}

contract Caller {
    ModifierEntrancy immutable c;
    constructor(ModifierEntrancy _c) { c = _c; }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function drop() external {
        c.airDrop();
    }
}
